//go:build linux

package process_test

import (
	"os"
	"os/exec"
	"time"

	. "github.com/mudler/go-processmanager"
	. "github.com/onsi/ginkgo"
	. "github.com/onsi/gomega"
)

// waitAfterExit starts a short-lived command with os/exec, gives it long enough
// to exit and be reaped by anything else that may be reaping, and returns what
// Wait reports. The sleep is several times the reaper's 100ms poll, so a
// running reaper has certainly claimed the child by the time Wait runs. That
// makes the check deterministic rather than a race.
func waitAfterExit() error {
	cmd := exec.Command("/bin/true")
	Expect(cmd.Start()).ToNot(HaveOccurred())
	time.Sleep(500 * time.Millisecond)
	return cmd.Wait()
}

var _ = Describe("Subreaper", func() {
	// A managed process that outlives each example, so the monitor goroutine
	// (and its reaper, when enabled) is running while we exec.
	run := func(opts ...Option) *Process {
		args := append([]Option{
			WithName("/bin/sleep"),
			WithArgs("60"),
			WithTemporaryStateDir(),
		}, opts...)
		p := New(args...)
		Expect(p.Run()).ToNot(HaveOccurred())
		return p
	}

	Context("by default", func() {
		It("leaves os/exec in the host program alone", func() {
			p := run()
			defer os.RemoveAll(p.StateDir())
			defer p.Stop()

			// Without the reaper this is the ordinary case: our child is ours
			// to wait for, and Wait reports its exit status.
			Expect(waitAfterExit()).ToNot(HaveOccurred())
		})
	})

	Context("when the caller asks for it", func() {
		It("reaps orphans, and so also claims the host program's children", func() {
			p := run(WithSubreaper(true))
			defer os.RemoveAll(p.StateDir())
			defer p.Stop()

			// This is the documented cost of opting in: the reaper's wait(-1)
			// takes the child before os/exec can, so Wait loses the exit
			// status. Asserting it keeps the trade-off visible, and pins that
			// the option is actually wired to the reaper.
			err := waitAfterExit()
			Expect(err).To(HaveOccurred())
			Expect(err.Error()).To(ContainSubstring("no child processes"))
		})
	})
})

package process_test

import (
	"os"
	"path/filepath"
	"sync"
	"time"

	. "github.com/mudler/go-processmanager"
	. "github.com/onsi/ginkgo"
	. "github.com/onsi/gomega"
)

var _ = Describe("ProcessManager", func() {
	Context("smoke tests", func() {
		It("starts", func() {
			p := New(
				WithName("/bin/bash"),
				WithArgs("-c", `
while true;
do sleep 1 && echo "test";
done`),
				WithTemporaryStateDir(),
			)
			dir := p.StateDir()
			defer os.RemoveAll(dir)
			Expect(p.Run()).ToNot(HaveOccurred())
			Eventually(func() string {
				c, _ := os.ReadFile(p.StdoutPath())
				return string(c)
			}, "2m").Should(ContainSubstring("test"))

			Expect(p.Stop()).ToNot(HaveOccurred())
		})

		It("stops by reading pid dir", func() {
			dir, err := os.MkdirTemp(os.TempDir(), "")
			Expect(err).ToNot(HaveOccurred())
			defer os.RemoveAll(dir)

			p := New(
				WithStateDir(dir),
				WithName("/bin/bash"),
				WithArgs("-c", `
while true;
do sleep 1 && echo "test";
done`),
			)
			Expect(p.Run()).ToNot(HaveOccurred())

			Eventually(func() string {
				c, _ := os.ReadFile(p.StdoutPath())
				return string(c)
			}, "2m").Should(ContainSubstring("test"))

			Eventually(func() bool {
				return New(
					WithStateDir(dir),
				).IsAlive()
			}, "2m").Should(BeTrue())

			Expect(New(
				WithStateDir(dir)).Stop()).ToNot(HaveOccurred())
		})

	})

	Context("config", func() {
		It("handles working directory", func() {
			dir1, err := os.MkdirTemp(os.TempDir(), "")
			Expect(err).ToNot(HaveOccurred())
			defer os.RemoveAll(dir1)
			dir2, err := os.MkdirTemp(os.TempDir(), "")
			Expect(err).ToNot(HaveOccurred())
			defer os.RemoveAll(dir2)

			p := New(
				WithStateDir(dir1),
				WithName("/bin/bash"),
				WithArgs("-c", `
pwd
`),
				WithWorkDir(dir2),
			)

			Expect(p.Run()).ToNot(HaveOccurred())

			Eventually(func() string {
				c, _ := os.ReadFile(p.StdoutPath())
				return string(c)
			}, "2m").Should(ContainSubstring(dir2))

		})
	})

	Context("exit codes", func() {
		It("correctly returns 0", func() {
			dir, err := os.MkdirTemp(os.TempDir(), "")
			Expect(err).ToNot(HaveOccurred())
			defer os.RemoveAll(dir)

			p := New(
				WithStateDir(dir),
				WithName("/bin/bash"),
				WithArgs("-c", `
echo "ok"
`),
			)

			Expect(p.Run()).ToNot(HaveOccurred())
			Eventually(func() bool {
				return New(
					WithStateDir(dir),
				).IsAlive()
			}, "2m").Should(BeFalse())
			e, err := New(WithStateDir(dir)).ExitCode()
			Expect(err).ToNot(HaveOccurred())
			Expect(e).To(Equal("0"))
		})
		It("correctly returns 2", func() {
			dir, err := os.MkdirTemp(os.TempDir(), "")
			Expect(err).ToNot(HaveOccurred())
			defer os.RemoveAll(dir)

			p := New(
				WithStateDir(dir),
				WithName("/bin/bash"),
				WithArgs("-c", `
exit 2
`),
			)

			Expect(p.Run()).ToNot(HaveOccurred())
			Eventually(func() bool {
				return New(
					WithStateDir(dir),
				).IsAlive()
			}, "2m").Should(BeFalse())
			e, err := New(WithStateDir(dir)).ExitCode()
			Expect(err).ToNot(HaveOccurred())
			Expect(e).To(Equal("2"))
		})
	})

	Context("concurrency", func() {
		// A bare Run/Stop cycle is enough to trip the race detector: the
		// library's own monitor goroutine polls IsAlive while the caller is in
		// Stop. This spec only asserts the normal lifecycle - its real
		// assertion is made by -race, so it must be run with it enabled.
		It("does not race between Stop, IsAlive and the monitor goroutine", func() {
			dir, err := os.MkdirTemp(os.TempDir(), "")
			Expect(err).ToNot(HaveOccurred())
			defer os.RemoveAll(dir)

			p := New(
				WithStateDir(dir),
				WithName("/bin/bash"),
				WithArgs("-c", `
echo "starting"
while true; do
  sleep 1
done
`),
				WithGracefulTimeout(2*time.Second),
			)
			Expect(p.Run()).ToNot(HaveOccurred())

			Eventually(func() string {
				c, _ := os.ReadFile(p.StdoutPath())
				return string(c)
			}, "10s").Should(ContainSubstring("starting"))

			// Widen the window by having callers read process state while the
			// monitor goroutine and Stop are both running.
			stopReaders := make(chan struct{})
			var readers sync.WaitGroup
			for i := 0; i < 4; i++ {
				readers.Add(1)
				go func() {
					defer readers.Done()
					for {
						select {
						case <-stopReaders:
							return
						default:
							p.IsAlive()
							p.CurrentPID()
						}
					}
				}()
			}

			Expect(p.Stop()).ToNot(HaveOccurred())
			close(stopReaders)
			readers.Wait()

			Eventually(func() bool {
				return p.IsAlive()
			}, "10s").Should(BeFalse())
			Expect(p.CurrentPID()).To(Equal(""))
		})
	})

	Context("single-use lifecycle", func() {
		// Run's "already started" guard is a check-then-act on p.proc with no
		// lock around it. Concurrent callers can all observe a nil p.proc, all
		// start a process and all launch a monitor goroutine - and every
		// monitor closes the same done channel when its Wait returns, so the
		// second one panics with "close of closed channel".
		It("starts exactly one process when Run is called concurrently", func() {
			dir, err := os.MkdirTemp(os.TempDir(), "")
			Expect(err).ToNot(HaveOccurred())
			defer os.RemoveAll(dir)

			p := New(
				WithStateDir(dir),
				WithName("/bin/bash"),
				WithArgs("-c", `echo "started"`),
			)

			const callers = 8
			errs := make([]error, callers)
			barrier := make(chan struct{})
			var callersDone sync.WaitGroup
			for i := 0; i < callers; i++ {
				callersDone.Add(1)
				go func(i int) {
					defer callersDone.Done()
					<-barrier
					errs[i] = p.Run()
				}(i)
			}
			close(barrier)
			callersDone.Wait()

			started := 0
			for _, err := range errs {
				if err == nil {
					started++
				}
			}
			Expect(started).To(Equal(1), "exactly one Run call may start a process")

			// Closing done is what a duplicate monitor goroutine would panic
			// on, so waiting for the process to exit is the real assertion.
			Eventually(p.Done(), "10s").Should(BeClosed())
		})

		It("refuses to re-run a handle whose process has exited", func() {
			dir, err := os.MkdirTemp(os.TempDir(), "")
			Expect(err).ToNot(HaveOccurred())
			defer os.RemoveAll(dir)

			p := New(
				WithStateDir(dir),
				WithName("/bin/bash"),
				WithArgs("-c", `echo "started"`),
			)

			Expect(p.Run()).ToNot(HaveOccurred())
			Eventually(p.Done(), "10s").Should(BeClosed())

			Expect(p.Run()).To(MatchError(ErrProcessAlreadyRun))
		})

		It("refuses to re-run a handle that was stopped", func() {
			dir, err := os.MkdirTemp(os.TempDir(), "")
			Expect(err).ToNot(HaveOccurred())
			defer os.RemoveAll(dir)

			p := New(
				WithStateDir(dir),
				WithName("/bin/bash"),
				WithArgs("-c", `
echo "started"
while true; do
  sleep 1
done
`),
				WithGracefulTimeout(2*time.Second),
			)

			Expect(p.Run()).ToNot(HaveOccurred())
			Eventually(func() string {
				c, _ := os.ReadFile(p.StdoutPath())
				return string(c)
			}, "10s").Should(ContainSubstring("started"))

			Expect(p.Stop()).ToNot(HaveOccurred())

			// Stop clears the pidfile, so nothing else would catch the reuse.
			Expect(p.Run()).To(MatchError(ErrProcessAlreadyRun))
		})

		It("allows retrying a Run that never started a process", func() {
			dir, err := os.MkdirTemp(os.TempDir(), "")
			Expect(err).ToNot(HaveOccurred())
			defer os.RemoveAll(dir)

			p := New(
				WithStateDir(dir),
				WithName(filepath.Join(dir, "does-not-exist")),
			)

			// A failed start burns nothing: the handle has no monitor goroutine
			// and no live process, so the caller may fix the cause and retry.
			Expect(p.Run()).To(HaveOccurred())
			Expect(p.Run()).ToNot(MatchError(ErrProcessAlreadyRun))
		})
	})

	Context("process group termination", func() {
		It("kills child processes when parent is stopped", func() {
			dir, err := os.MkdirTemp(os.TempDir(), "")
			Expect(err).ToNot(HaveOccurred())
			defer os.RemoveAll(dir)

			// Start a parent process that spawns a child process
			p := New(
				WithStateDir(dir),
				WithName("/bin/bash"),
				WithArgs("-c", `
echo "starting"

# Start a child process that runs indefinitely
(
  while true; do
    sleep 1
  done
) &

# Parent also runs indefinitely
while true; do
  sleep 1
done
`),
			)
			Expect(p.Run()).ToNot(HaveOccurred())

			// Wait for the process to start
			Eventually(func() string {
				c, _ := os.ReadFile(p.StdoutPath())
				return string(c)
			}, "5s").Should(ContainSubstring("starting"))

			// Verify process is alive
			Expect(p.IsAlive()).To(BeTrue())

			// Stop the parent process (should kill entire process group)
			Expect(p.Stop()).ToNot(HaveOccurred())

			// Verify the process is no longer alive
			Eventually(func() bool {
				return p.IsAlive()
			}, "10s").Should(BeFalse())
		})
	})
})

